INSERT INTO events (hospital_id, title, category, target_part, original_price, discount_price, image_url, description) 
SELECT id, '실루엣 소프트 8줄 + 큐티엘 4줄', '피부', '체내에서 분해되는 PLA성분의 특수한 의료용 실을 이용한 비수술적 방법의 페이스 리모델링 볼륨 실리프팅. 인체에 흡수되는 양방향 3D CONE 모양의 실. SILHOUETTE SO', 4000000, 3200000, 'https://cd-fnb.co.kr/data/editor/2605/b804b2f0075b5cffe8a7bbb2c6eab3fc_1778116229_5176.jpg', 'Re-shaping과 Tightening을 한번에~!, 즉각적인 볼륨 효과, 우수한 피부 고정력, 낮은 피부자극' 
FROM hospitals WHERE name = '청담FnB의원' 
AND NOT EXISTS (SELECT 1 FROM events e2 WHERE e2.hospital_id = hospitals.id AND e2.title = '실루엣 소프트 8줄 + 큐티엘 4줄') LIMIT 1;
